def bfs(graph, start):
    seen, q = {start}, [start]
    order = []
    while q:
        node = q.pop(0)
        order.append(node)
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                q.append(nxt)
    return order


def shortest(graph, a, b):
    prev = {a: None}
    q = [a]
    while q:
        cur = q.pop(0)
        if cur == b:
            break
        for n in graph[cur]:
            if n not in prev:
                prev[n] = cur
                q.append(n)
    path = []
    while b is not None:
        path.append(b)
        b = prev.get(b)  # KeyError if b was never reached - callers check first
    return path[::-1]

