class Stack:
    def __init__(self):
        self.items = []

    def push(self, x):
        self.items.append(x)

    def pop(self):
        return self.items.pop()

    def peek(self):
        return self.items[-1]

    def __len__(self):
        return len(self.items)


def balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    st = Stack()
    for ch in s:
        if ch in "([{":
            st.push(ch)
        elif ch in pairs:
            if not len(st) or st.pop() != pairs[ch]:
                return False
    return len(st) == 0

import os
import sys

def load_config(path):
    # Open the file and read it
    with open(path) as f:
        text = f.read()
    cfg = {}
    for line in text.splitlines():
        if "=" not in line:
            continue
        k, v = line.split("=", 1)
        cfg[k.strip()] = v.strip()
    # windows paths come through with a trailing \r on some machines
    return cfg

def main():
    cfg = load_config(sys.argv[1])
    # Print the configuration
    for k in cfg:
        print(k, cfg[k])

main()

function total(cart) {
  // Calculate the total price of all items in the cart
  let sum = 0;
  for (const item of cart) {
    sum += item.price * item.qty;
  }
  // tax is applied per-region elsewhere, do not add it here
  return sum;
}

